---
import Layout from '../layouts/Layout.astro';
import SoftwareCard from '../components/SoftwareCard.astro';
import { softwareData, categories, searchSoftware } from '../data/software';

// Get search query from URL parameters
const url = Astro.url;
const query = url.searchParams.get('q') || '';
const category = url.searchParams.get('category') || '';

let searchResults = softwareData;

if (query) {
	searchResults = searchSoftware(query);
}

if (category) {
	searchResults = searchResults.filter(software => software.category === category);
}
---

<Layout title="Search - Open Source Software Alternatives">
	<div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
		<!-- Search Header -->
		<div class="text-center mb-12">
			<h1 class="text-4xl lg:text-5xl font-bold text-secondary-900 mb-6">
				Search Alternatives
			</h1>
			<p class="text-xl text-secondary-600 max-w-3xl mx-auto mb-8">
				Find the perfect open source alternative to your favorite software.
			</p>

			<!-- Search Form -->
			<form method="GET" action="/search" class="max-w-2xl mx-auto">
				<div class="flex flex-col sm:flex-row gap-4">
					<div class="flex-1 relative">
						<input 
							type="text" 
							name="q" 
							value={query}
							placeholder="Search software, tags, or categories..."
							class="w-full px-4 py-3 pl-12 text-lg border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none"
						/>
						<svg class="absolute left-4 top-1/2 transform -translate-y-1/2 w-5 h-5 text-secondary-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
							<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/>
						</svg>
					</div>
					<select 
						name="category" 
						value={category}
						class="px-4 py-3 text-lg border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 outline-none bg-white"
					>
						<option value="">All Categories</option>
						{categories.map((cat) => (
							<option value={cat}>{cat}</option>
						))}
					</select>
					<button 
						type="submit"
						class="px-6 py-3 text-lg font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-700 transition-colors"
					>
						Search
					</button>
				</div>
			</form>
		</div>

		<!-- Results -->
		{query || category ? (
			<div class="mb-8">
				<h2 class="text-2xl font-semibold text-secondary-900 mb-2">
					{searchResults.length} result{searchResults.length !== 1 ? 's' : ''} found
					{query && ` for "${query}"`}
					{category && ` in ${category}`}
				</h2>
			</div>
		) : null}

		{searchResults.length === 0 ? (
			<div class="text-center py-20">
				<div class="w-20 h-20 bg-secondary-100 rounded-full flex items-center justify-center mx-auto mb-6">
					<svg class="w-10 h-10 text-secondary-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
						<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/>
					</svg>
				</div>
				<h3 class="text-xl font-semibold text-secondary-900 mb-2">No results found</h3>
				<p class="text-secondary-600 mb-6">
					Try different keywords or browse our categories instead.
				</p>
				<div class="flex flex-col sm:flex-row gap-4 justify-center">
					<a href="/categories" class="inline-flex items-center px-4 py-2 text-sm font-medium text-primary-600 bg-primary-50 rounded-lg hover:bg-primary-100 transition-colors">
						Browse Categories
					</a>
					<a href="/" class="inline-flex items-center px-4 py-2 text-sm font-medium text-secondary-600 bg-secondary-50 rounded-lg hover:bg-secondary-100 transition-colors">
						Go Home
					</a>
				</div>
			</div>
		) : (
			<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
				{searchResults.map((software) => (
					<SoftwareCard 
						name={software.name}
						description={software.description}
						category={software.category}
						license={software.license}
						website={software.website}
						github={software.github}
						tags={software.tags}
						featured={software.featured}
					/>
				))}
			</div>
		)}

		<!-- Popular Searches -->
		{!query && !category && (
			<div class="mt-20">
				<h3 class="text-2xl font-bold text-secondary-900 mb-8 text-center">Popular Searches</h3>
				<div class="grid grid-cols-2 md:grid-cols-4 gap-4">
					{[
						{ query: 'photoshop', label: 'Photoshop alternatives' },
						{ query: 'office', label: 'Office suite' },
						{ query: 'video editor', label: 'Video editing' },
						{ query: 'browser', label: 'Web browsers' },
						{ query: 'notes', label: 'Note-taking' },
						{ query: '3d modeling', label: '3D software' },
						{ query: 'audio', label: 'Audio editing' },
						{ query: 'cloud storage', label: 'Cloud storage' }
					].map((item) => (
						<a 
							href={`/search?q=${encodeURIComponent(item.query)}`}
							class="bg-white rounded-lg p-4 border border-secondary-200 hover:border-primary-300 hover:shadow-md transition-all duration-300 text-center"
						>
							<span class="text-secondary-900 font-medium">{item.label}</span>
						</a>
					))}
				</div>
			</div>
		)}
	</div>
</Layout>
